svg.script:
(() => {
  const roots = document.querySelectorAll("svg[data-knot-motion]");

  for (const svg of roots) {
    if (svg.hasAttribute("data-knot-ready")) continue;
    svg.setAttribute("data-knot-ready", "");
    const control = svg.closest("button") || svg;
    const reduceMotion = window.matchMedia("(prefers-reduced-motion: reduce)");
    const clamp = (n) => Math.max(0, Math.min(1, n));
    const phase = (t, a, b) => {
      const u = clamp((t - a) / (b - a));
      return u * u * (3 - 2 * u);
    };
    const coordinates = (d) => d.match(/-?\d*\.?\d+/g).map(Number);
    const timing = {
      spine:  [0, 0.87, -4.1, 0.6],
      return: [0.07, 1, 1.8, 4.8],
      face:   [0.015, 0.94, 2.6, -6.3]
    };
    const faces = [...svg.querySelectorAll("[data-face]")].map((path) => {
      const closed = path.getAttribute("d");
      const open = path.getAttribute("data-open");
      return { path, closed, open, a: coordinates(closed), b: coordinates(open),
        timing: timing[path.dataset.face] };
    });
    const wires = svg.querySelectorAll("[data-wire]");
    const holes = svg.querySelectorAll("[data-port]");
    const stops = [...svg.querySelectorAll("linearGradient stop")].map((stop) => {
      const ink = stop.getAttribute("stop-color").slice(1);
      const rgb = [0, 2, 4].map((i) => parseInt(ink.slice(i, i + 2), 16));
      const flat = stop.getAttribute("data-flat").slice(1);
      const flatInk = [0, 2, 4].map((i) => parseInt(flat.slice(i, i + 2), 16));
      return {stop, rgb, flatInk};
    });
    let position = 0, velocity = 0, goal = 0, frame = 0, previous = 0;
    let hovering = false, pointerType = "";

    function draw(position) {
      const t = clamp(position);
      for (const { path, closed, open, a, b, timing: [start, end, dx, dy] } of faces) {
        const u = phase(t, start, end);
        if (u === 0 || u === 1) {
          path.setAttribute("d", u === 0 ? closed : open);
          path.removeAttribute("transform");
          continue;
        }
        const p = a.map((v, i) => +(v + (b[i] - v) * u).toFixed(3));
        path.setAttribute("d", "M" + p[0] + " " + p[1] + "C" + p.slice(2).join(" ") + "Z");
        const lift = 4 * u * (1 - u);
        path.setAttribute("transform", "translate(" + (dx * lift) + " " + (dy * lift) + ")");
      }
      for (const wire of wires) {
        const u = phase(t, Number(wire.dataset.wire), 0.90);
        wire.setAttribute("stroke-dashoffset", 1 - u);
        wire.setAttribute("opacity", phase(t, 0.14, 0.48));
      }
      const punch = phase(t, 0.73, 0.985);
      for (const port of holes) port.setAttribute("r", Number(port.dataset.port) * punch);
      const flatten = phase(t, 0.36, 0.95);
      for (const {stop, rgb, flatInk} of stops) {
        const color = rgb.map((c, i) => Math.round(c + (flatInk[i] - c) * flatten));
        stop.setAttribute("stop-color", "rgb(" + color.join(",") + ")");
      }
    }

    function finish() {
      if (frame) cancelAnimationFrame(frame);
      frame = 0;
      velocity = 0;
      position = goal;
      draw(goal);
    }

    // A critically damped spring preserves velocity if the pointer reverses
    // direction halfway through a fold.
    function tick(now) {
      const dt = Math.min((now - previous) / 1000, 0.08);
      previous = now;
      const omega = goal ? 15.5 : 19;
      const offset = position - goal;
      const c = velocity + omega * offset;
      const decay = Math.exp(-omega * dt);
      position = goal + (offset + c * dt) * decay;
      velocity = (velocity - omega * c * dt) * decay;
      if (Math.abs(position - goal) < 0.001 && Math.abs(velocity) < 0.022) {
        finish();
      } else {
        draw(position);
        frame = requestAnimationFrame(tick);
      }
    }

    function setGoal(open) {
      control.setAttribute("aria-pressed", String(open));
      svg.dataset.state = open ? "open" : "tied";
      if (goal === Number(open)) return;
      goal = Number(open);
      if (reduceMotion.matches) {
        finish();
      } else if (!frame) {
        previous = performance.now();
        frame = requestAnimationFrame(tick);
      }
    }

    control.addEventListener("pointerenter", (e) => {
      if (e.pointerType === "touch") return;
      hovering = true;
      setGoal(true);
    });
    control.addEventListener("pointerleave", (e) => {
      if (e.pointerType === "touch") return;
      hovering = false;
      setGoal(false);
    });
    control.addEventListener("pointerdown", (e) => { pointerType = e.pointerType; });
    control.addEventListener("click", (e) => {
      if (pointerType === "touch" || e.detail === 0) {
        hovering = false;
        setGoal(!goal);
      }
    });
    control.addEventListener("keydown", (e) => {
      if (e.key === "Escape") {
        hovering = false;
        setGoal(false);
      } else if (control === svg && (e.key === "Enter" || e.key === " ")) {
        e.preventDefault();
        if (e.repeat) return;
        hovering = false;
        setGoal(!goal);
      }
    });
    control.addEventListener("blur", () => {
      setGoal(hovering);
    });
    window.addEventListener("blur", () => {
      hovering = false;
      setGoal(false);
    });
    reduceMotion.addEventListener("change", () => {
      if (reduceMotion.matches) finish();
    });
    setGoal(false);
  }
})();
